def _get_import_for_qualname(qualname: str) ->str:
    return qualname.split(".")[-1]


def get_imports_for_annotation(anno: Any) ->ImportMap:
    imports = ImportMap()
    if is_forward_ref(anno):
        # Forward references don't need imports
        return imports
    if is_any(anno):
        # Any doesn't need imports
        return imports
    if is_generic(anno):
        # For generic types, we need to handle the base type and its arguments
        base = qualname_of_generic(anno)
        if base:
            imports[base.split(".")[:-1]].add(base.split(".")[-1])
        # Handle arguments
        args = getattr(anno, "__args__", None)
        if args:
            for arg in args:
                imports.merge(get_imports_for_annotation(arg))
        return imports
    if hasattr(anno, "__module__") and anno.__module__:
        if anno.__module__ == "typing":
            imports["typing"].add(anno.__name__)
        elif anno.__module__ != "builtins":
            imports[anno.__module__].add(anno.__name__)
    return imports
